from flask import Flask, request
import subprocess
import ipaddress

app = Flask(__name__)

@app.route('/tools/ping')
def ping_host():
    host = request.args.get('host', '127.0.0.1')
    try:
        # Fix: Validate that the input is a legitimate IP address
        ipaddress.ip_address(host)
    except ValueError:
        return {"error": "Invalid IP address"}, 400

    # Use subprocess.run with a list, avoiding shell execution
    res = subprocess.run(["ping", "-c", "1", host], capture_output=True, text=True)
    return {"output": res.stdout}

from flask import Flask, request, abort
import zipfile
import os

app = Flask(__name__)

@app.route('/compress')
def compress_folder():
    folder_name = request.args.get('folder')
    # Fix: Use native Python libraries for compression to avoid the shell entirely.
    if not folder_name or ".." in folder_name:
        abort(400)

    zip_path = f"{folder_name}.zip"
    with zipfile.ZipFile(zip_path, 'w') as zipf:
        for root, dirs, files in os.walk(folder_name):
            for file in files:
                zipf.write(os.path.join(root, file))

    return {"status": "compressed"}

